"""Build portable, offline HTML viewers from measured MATLAB/Simulink results."""
from pathlib import Path
import csv, json, html
ROOT=Path(__file__).resolve().parents[1]
def rows(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
STYLE='''*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#172b42;font:16px/1.55 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:42px 28px}header{margin-bottom:30px}.eyebrow{color:#41628a;font-size:12px;font-weight:800;letter-spacing:2px}h1{font-size:clamp(32px,5vw,54px);line-height:1.1;margin:12px 0}h2{font-size:20px;margin:0 0 14px}.intro{max-width:850px;color:#53677f}a{color:#006cb6}.badge{display:inline-block;background:#dcece8;border:1px solid #b4d8cd;color:#17634b;border-radius:20px;padding:4px 12px;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border:1px solid #dce3eb;border-radius:15px;padding:24px;margin-bottom:20px;box-shadow:0 4px 16px #172b4205}.metric{font-size:32px;font-weight:750}.muted,small{color:#64748b}.controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap}input[type=range]{flex:1;min-width:150px;accent-color:#007ea5}select,button{font:inherit;background:#f8fafc;border:1px solid #bac8d6;border-radius:8px;padding:8px 14px}button{cursor:pointer;background:#133953;color:white}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #28b5d5;outline-offset:3px}svg{display:block;width:100%;height:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid #e3e9ef}th{color:#5d728b;font-size:12px;text-transform:uppercase}.note{border-left:4px solid #d49a28;padding:12px 18px;background:#fff8e8;font-size:14px}.flex{display:grid;grid-template-columns:1.4fr 1fr;gap:20px}footer{font-size:13px;color:#64748b;padding:15px 0}.scroll{overflow-x:auto}@media(max-width:700px){main{padding:24px 14px}.grid,.flex{grid-template-columns:1fr}h1{font-size:34px}.card{padding:18px}}'''
def page(title,content,script):
    return '<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+'</title><style>'+STYLE+'</style><main>'+content+'<footer>Portfolio de Alejandro Pedersen · Código MIT · Creación asistida por IA · Resultados reproducibles, sin afirmación de despliegue industrial.</footer></main><script>'+script+'</script></html>'

b=ROOT; summary=json.loads((b/'results/summary.json').read_text()); data=rows(b/'results/test_predictions.csv'); stress=rows(b/'results/gain_stress.csv')
content='''<header><div class="eyebrow">PROYECTO 01 / MATLAB / MANTENIMIENTO INDUSTRIAL</div><h1>Bearing Watch</h1><p class="intro">Del acelerómetro a una decisión explicable. Detector de anomalías calibrado con registros sanos, evaluación separada por carga y alarmas con persistencia.</p><span class="badge">Datos reales CWRU · Evaluación local reproducida</span></header>
<section class="grid"><div class="card"><div class="muted">Ventanas de prueba</div><div class="metric">206</div><small>Cuatro registros · 3 hp · un banco de ensayos</small></div><div class="card"><div class="muted">Sensibilidad al umbral elegido</div><div class="metric" id="sensitivity"></div><small id="tp"></small></div><div class="card"><div class="muted">Tasa de falsas alarmas</div><div class="metric" id="falseRate"></div><small id="fp"></small></div></section>
<section class="card"><h2>Explora el compromiso de detección</h2><div class="controls"><label for="threshold">Umbral de score</label><input id="threshold" type="range" min="0" max="35" value="3" step="0.1"><output id="thresholdValue"></output><button id="reset">Restaurar benchmark</button></div><svg id="chart" viewBox="0 0 1000 340" role="img" aria-label="Score de cada ventana y umbral de detección"></svg><small>Ventanas agrupadas por registro, no una línea temporal continua. Azul: sano; naranja: defecto. El deslizador es exploratorio: no modifica el detector ni los resultados guardados.</small></section>
<div class="flex"><section class="card"><h2>Una limitación que importa</h2><p>Un cambio de ganancia del sensor desplaza el RMS. El sistema necesita una calibración consistente con la adquisición.</p><div class="scroll"><table><thead><tr><th>Ganancia</th><th>Sensibilidad</th><th>Falsas alarmas</th></tr></thead><tbody>'''+''.join(f'<tr><td>{float(r["AcquisitionGain"]):g}×</td><td>{float(r["Sensitivity"]):.1%}</td><td>{float(r["FalseAlarmRate"]):.1%}</td></tr>' for r in stress)+'''</tbody></table></div></section><section class="card"><h2>Qué revisar en el código</h2><p>Canal exacto por archivo, separación de entrenamiento y prueba, rechazo de sensores planos y una regresión que evita cargar datos del archivo 98 al calibrar con el 99.</p><p><a href="../README.md">README</a> · <a href="../results/summary.json">Métricas JSON</a> · <a href="defensa-es.md">Guía de entrevista</a></p></section></div><p class="note">El resultado del benchmark no implica fiabilidad en planta. Los defectos fueron inducidos en laboratorio; las ventanas están correlacionadas. No se estima vida útil ni se acciona una parada de máquina.</p>'''
script='const D='+json.dumps(data,separators=(',',':'))+''';const base=3;const input=document.getElementById('threshold');function update(){const th=+input.value;let tp=0,fp=0,n=0,p=0;D.forEach(d=>{let actual=d.Label!=='healthy',flag=+d.Score>th;if(actual){p++;tp+=flag}else{n++;fp+=flag}});document.getElementById('sensitivity').textContent=(100*tp/p).toFixed(1)+' %';document.getElementById('falseRate').textContent=(100*fp/n).toFixed(1)+' %';document.getElementById('tp').textContent=tp+' / '+p+' ventanas con defecto detectadas';document.getElementById('fp').textContent=fp+' / '+n+' ventanas sanas señaladas';document.getElementById('thresholdValue').textContent=th.toFixed(1);let s='';for(let y=0;y<=35;y+=5){let py=290-y*7.2;s+='<line x1="55" y1="'+py+'" x2="970" y2="'+py+'" stroke="#e2e8f0"/><text x="20" y="'+(py+5)+'" font-size="13" fill="#64748b">'+y+'</text>'}D.forEach((d,i)=>{s+='<circle cx="'+(55+i*915/(D.length-1))+'" cy="'+(290-(+d.Score)*7.2)+'" r="3.5" fill="'+(d.Label==='healthy'?'#007ea5':'#da8130')+'"><title>'+d.Label+' / score '+(+d.Score).toFixed(2)+'</title></circle>'});const y=290-th*7.2;s+='<line x1="55" y1="'+y+'" x2="970" y2="'+y+'" stroke="#b33e55" stroke-width="2" stroke-dasharray="7 5"/><text x="55" y="325" font-size="13" fill="#64748b">Sano → pista interior → bola → pista exterior</text>';document.getElementById('chart').innerHTML=s}input.addEventListener('input',update);document.getElementById('reset').onclick=()=>{input.value=base;update()};update();'''
(b/'docs/demo.html').write_text(page('Bearing Watch — demo',content,script),encoding='utf-8')


print("Offline viewer generated from results.")
